import itertools

def generate_patterns():
    patterns_by_count = {i: [] for i in range(10)}

    for bits in range(2**9):
        cells_lit = set()
        for idx in range(9):
            if (bits >> idx) & 1:
                cells_lit.add((idx//3, idx%3))

        if not cells_lit:
            continue

        # Build pattern
        pat = [[0]*3 for _ in range(3)]
        for r,c in cells_lit:
            pat[r][c] = 1

        # Generate all rotations and flips
        def rotate(pat):
            return [[pat[2-c][r] for c in range(3)] for r in range(3)]

        def flip(pat):
            return [[pat[c][2-r] for c in range(3)] for r in range(3)]

        versions = [pat]
        r1 = rotate(pat); versions.append(r1)
        r2 = rotate(r1); versions.append(r2)
        r3 = rotate(r2); versions.append(r3)
        f1 = flip(pat); versions.append(f1)
        rf1 = rotate(f1); versions.append(rf1)
        rf2 = rotate(rf1); versions.append(rf2)
        rf3 = rotate(rf2); versions.append(rf3)

        # Use canonical representation
        canons = [tuple(tuple(row) for row in v) for v in versions]
        min_form = min(canons)

        patterns_by_count[len(cells_lit)].append(min_form)

    # Deduplicate
    unique = {}
    for count, pats in patterns_by_count.items():
        seen = set()
        keep = []
        for p in pats:
            if p not in seen:
                seen.add(p)
                keep.append(p)
        unique[count] = keep

    return unique

